  " if(b.hasAttribute('data-summary')){if(!commitDraft())return;unsaved=false;E.sel=null;document.body.classList.remove('mobile-panel');panelSummary();drawGraph();saveHash();return;}",
  " if(b.hasAttribute('data-sources'))return sourcesPanel();",
