  "});",
  "$('#graph').addEventListener('click',ev=>{",
  " if(skipClick){skipClick=false;return;}const n=ev.target.closest('[data-id]'),e=ev.target.closest('[data-edge]');if(n)return setSelected(n.dataset.id);if(e)return panelEdge(e.dataset.edge);if(!commitDraft())return;unsaved=false;E.sel=null;panelSummary();drawGraph();saveHash();",
