  "$('#graph').addEventListener('keydown',ev=>{const n=ev.target.closest('[data-id]');if(n&&(ev.key==='Enter'||ev.key===' ')){ev.preventDefault();setSelected(n.dataset.id);}if(ev.key==='Escape'){document.body.classList.remove('mobile-panel');}});",
  "$('#graph').addEventListener('pointerdown',ev=>{",
