  " drag={id:n?.dataset.id,p,last:p,start:{x:ev.clientX,y:ev.clientY},moved:false};",
  "});",
  "$('#graph').addEventListener('pointermove',ev=>{if(!drag)return;const p=new DOMPoint(ev.clientX,ev.clientY).matrixTransform($('#graph').getScreenCTM().inverse());if(!drag.moved&&Math.hypot(ev.clientX-drag.start.x,ev.clientY-drag.start.y)>4){drag.moved=true;$('#graph').setPointerCapture(ev.pointerId);}if(!drag.moved)return;if(drag.id){POS[drag.id].x+=p.x-drag.last.x;POS[drag.id].y+=p.y-drag.last.y;drag.last=p;drawGraph();}else{VB.x-=p.x-drag.p.x;VB.y-=p.y-drag.p.y;applyView();}});",
